import {VoiceDemand} from '../../src/streaming/voiceDemand';
import {completeGreeting} from '../../src/streaming/completeGreeting';
import {VerifiedPcmSource,type PcmEnvelope} from '../../src/streaming/pcmProvenance';
import {observeDiagnostic,diagnosticReason} from '../../src/streaming/sessionDiagnostics';
import type {Language} from '../../src/types';
import type {Alignment} from '../../server/continuousVoice';
import {assertDanishVoice,type VoiceIdentity} from '../../src/streaming/voiceIdentity';
export class ContinuousVoice {
 identity?:VoiceIdentity;provenance?:VerifiedPcmSource;private pendingPcm?:PcmEnvelope;private language?:Language;private greeting?:string;private greetingTimer?:ReturnType<typeof setTimeout>;private socket?:WebSocket;private failed?:Error;private ending=false;private readyReject?:(e:Error)=>void;private doneResolve?:()=>void;private doneReject?:(e:Error)=>void;private timer?:ReturnType<typeof setTimeout>;private signal?:AbortSignal;private pendingAlignment?:Alignment;private ended=false;private sentChars=0;private sentenceSent=false;private demandTimer?:ReturnType<typeof setInterval>;private sentAudioChars=0;private alignedAudioChars=0;private flushedAudioChars=0;private hasAudio=false;private initialFlushRequested=false;private submittedAudioText='';
 private demand=new VoiceDemand();private demandSentAt?:number;private diagnosticSamples=0;private lastPcmAt?:number;private recoverySamples=0;private recoveryAttempts=0;
 private trace(event:string,data:Record<string,unknown>={}){observeDiagnostic(this.options.trace,event,{requestId:this.identity?.requestId,providerRequestId:this.identity?.providerRequestId,ending:this.ending,hasAudio:this.hasAudio,sentCharacters:this.sentAudioChars,pendingCharacters:Math.max(0,this.sentAudioChars-this.alignedAudioChars),...data});}
 private aborted=()=>this.fail(new DOMException('Call ended','AbortError'));
 constructor(private audio:(bytes:Uint8Array,alignment?:Alignment,voice?:VoiceIdentity)=>void,private earlyFirstClause=false,private quality=false,private failure?:(error:Error)=>void,private options:{simultaneous?:boolean;prosodyMs?:number;expectedVoice?:VoiceIdentity;queuedMs?:()=>number;trace?:(type:string,data:Record<string,unknown>)=>void}={}){if(options.prosodyMs!==undefined&&![150,250,350,500].includes(options.prosodyMs))throw new Error('Use a supported 150–500ms prosody buffer.');}
 private fail(e:Error){if(this.ended||this.failed)return;this.trace('voice.failed',{classification:diagnosticReason(e)});this.failed=e;this.readyReject?.(e);this.doneReject?.(e);this.close();if(e.name!=='AbortError')this.failure?.(e);}
 async open(language:Language,signal:AbortSignal){signal.throwIfAborted();this.signal=signal;this.language=language;this.socket=new WebSocket(`${location.protocol==='https:'?'wss:':'ws:'}//${location.host}/api/voice/live?language=${language}${this.options.simultaneous?'&profile=simultaneous':this.quality?'&profile=quality':this.earlyFirstClause?'&profile=fast':''}${this.options.trace?'&diagnostics=1':''}`);this.socket.binaryType='arraybuffer';await new Promise<void>((resolve,reject)=>{this.readyReject=reject;this.trace('voice.setup_timeout_started',{timeoutMs:10000,deadlineAt:performance.now()+10000,clock:'browser-performance.now'});this.timer=setTimeout(()=>{this.trace('voice.setup_timeout_expired',{timeoutMs:10000});this.fail(new Error('Continuous voice unavailable.'));},10000);signal.addEventListener('abort',this.aborted,{once:true});const socket=this.socket!;this.socket!.onmessage=e=>{if(signal.aborted||this.ended||this.failed||this.socket!==socket)return;try{if(e.data instanceof ArrayBuffer){const receivedAt=performance.now();if(!this.identity)throw new Error('Voice audio arrived without provider identity.');if(language==='da')assertDanishVoice(this.identity,this.options.expectedVoice);const pcm=new Uint8Array(e.data);if(language==='da'){if(!this.pendingPcm||!this.provenance)throw new Error('PCM arrived without its provenance envelope.');const started=performance.now();this.provenance.accept(pcm,this.pendingPcm);this.trace('voice.pcm_verified',{verificationMs:performance.now()-started,firstSample:this.pendingPcm.sampleStart,lastSample:this.pendingPcm.sampleEnd-1,pcmBlockSequence:this.pendingPcm.sequence});}if(this.demandSentAt!==undefined){this.demand.observe(receivedAt-this.demandSentAt);this.demandSentAt=undefined;}this.lastPcmAt=receivedAt;this.hasAudio=true;this.diagnosticSamples+=e.data.byteLength/2;this.trace('voice.pcm_received',{providerAt:receivedAt,samples:e.data.byteLength/2,totalSamples:this.diagnosticSamples});if(this.pendingAlignment)for(const span of this.pendingAlignment.chars)for(const char of span){if(/^\s$/.test(char)&&!/^\s$/.test(this.submittedAudioText[this.alignedAudioChars]??''))continue;this.alignedAudioChars+=char.length;}this.audio(pcm,this.pendingAlignment,this.identity);this.pendingAlignment=undefined;this.pendingPcm=undefined;return;}const event=JSON.parse(e.data);if(event.type==='diagnostic')this.trace(event.event,event.data);if(event.type==='ready'){if(this.identity)throw new Error('Voice identity changed during the output stream.');if(language==='da')assertDanishVoice(event.voice,this.options.expectedVoice);else if(event.voice?.provider!=='ElevenLabs')throw new Error('Unexpected voice provider.');this.identity=Object.freeze({...event.voice});if(language==='da')this.provenance=new VerifiedPcmSource(this.identity!,'elevenlabs-ws');clearTimeout(this.timer);this.readyReject=undefined;if(this.options.simultaneous&&this.options.queuedMs)this.demandTimer=setInterval(()=>this.flushForDemand(),50);this.options.trace?.('VOICE_READY',{...this.identity});resolve();}if(event.type==='alignment'){if(language==='da'){if(this.pendingPcm||!this.identity||!event.voice||event.voice.requestId!==this.identity.requestId||!Number.isInteger(event.sequence)||!Number.isInteger(event.sampleStart)||!Number.isInteger(event.sampleEnd)||event.samples!==event.sampleEnd-event.sampleStart||event.requestId!==this.identity.requestId)throw new Error('Invalid PCM provenance envelope.');this.pendingPcm={sequence:event.sequence,sampleStart:event.sampleStart,sampleEnd:event.sampleEnd,requestId:event.requestId};}if(event.voice&&(event.voice.requestId!==this.identity?.requestId||event.voice.provider!==this.identity?.provider||event.voice.voiceId!==this.identity?.voiceId||event.voice.modelId!==this.identity?.modelId))throw new Error('Audio provenance changed during the output stream.');this.pendingAlignment=event.alignment;}if(event.type==='flushed')this.options.trace?.('VOICE_FLUSH_CONFIRMED',event);if(event.type==='error')this.fail(new Error(`ElevenLabs voice stopped (${event.code??'unavailable'}). End and retry; no automatic replay.`));if(event.type==='done'){if(this.pendingPcm)throw new Error('Missing PCM for provenance envelope.');this.provenance?.seal();this.trace('voice.done_received');if(!this.ending)return this.fail(new Error('Premature voice completion.'));this.ended=true;this.doneResolve?.();this.close();}}catch{this.fail(new Error('ElevenLabs voice unavailable or identity rejected. No fallback audio.'));}};this.socket!.onerror=()=>this.fail(new Error('Continuous voice unavailable.'));this.socket!.onclose=()=>{this.trace('voice.transport_closed');if(!this.ended&&!this.failed)this.fail(new Error('Continuous voice disconnected. No automatic replay.'));};});}
 send(text:string){
  this.signal?.throwIfAborted();if(this.failed)throw this.failed;if(this.ending)throw new Error('Voice already finalized.');if(this.socket?.readyState!==WebSocket.OPEN)throw new Error('Voice connection is closed.');
  if(!this.greeting&&((this.options.simultaneous&&text.trim().length<=32&&text.trim().split(/\s+/).length<=4&&/[,.!?]$/.test(text.trim()))||(this.language==='da'&&this.sentChars===0&&/^(?:hej|goddag|hallo)[,.!?]*$/i.test(text.trim())))){this.greeting=text;this.greetingTimer=setTimeout(()=>{const held=this.greeting;this.greeting=undefined;if(held){try{this.sendNow(held);}catch(error){this.fail(error instanceof Error?error:new Error('Voice unavailable.'));}}},this.options.prosodyMs??250);return;}
  if(this.greeting){clearTimeout(this.greetingTimer);text=this.greeting.trimEnd()+' '+text;this.greeting=undefined;}
  this.sendNow(text);
 }
 private sendNow(text:string){this.signal?.throwIfAborted();if(this.failed)throw this.failed;if(this.ending||this.socket?.readyState!==WebSocket.OPEN||this.socket.bufferedAmount>256*1024)throw new Error('Voice queue exceeded its limit.');const initialClause=this.earlyFirstClause&&this.sentChars===0&&text.length<50&&/[,.!?;:]$/.test(text.trim());this.sentChars+=text.length;const initialSentence=!this.sentenceSent&&(/[.!?]$/.test(text.trim())||completeGreeting(text))&&this.sentChars<50;if(/[.!?]$/.test(text.trim()))this.sentenceSent=true;this.recoveryAttempts=0;this.submittedAudioText+=text.trimEnd()+' ';this.sentAudioChars=this.submittedAudioText.length;this.options.trace?.('ELEVENLABS_TEXT_SENT',{text,textCharacters:text.length,requestId:this.identity?.requestId,sentCharacters:this.sentAudioChars});this.socket.send(JSON.stringify({type:'text',text,initialSentence,initialClause}));if(!this.initialFlushRequested&&!/^(?:hej|goddag|hallo)[,.!?]*$/i.test(text.trim())&&(initialSentence||initialClause)){this.initialFlushRequested=true;this.flushedAudioChars=this.sentAudioChars;}this.flushForDemand();}
 private flushForDemand(){
  const bufferMs=this.options.queuedMs?.()??Infinity,pending=this.sentAudioChars-this.alignedAudioChars;
  if(this.failed||this.ending||this.ended||this.signal?.aborted||!this.options.simultaneous||pending<=0)return;
  const newText=this.flushedAudioChars<this.sentAudioChars;
  // One recovery per PCM-progress frontier, at most twice per submitted range.
  // Flush only existing text; never resend speech, reconnect, or hold playback.
  const stalled=!newText&&bufferMs<=250&&this.lastPcmAt!==undefined&&performance.now()-this.lastPcmAt>=750&&this.diagnosticSamples>this.recoverySamples&&this.recoveryAttempts<2;
  if(!this.demand.shouldFlush(bufferMs,pending,newText)&&!stalled)return;
  try{
   this.flushedAudioChars=this.sentAudioChars;
   if(stalled){this.recoverySamples=this.diagnosticSamples;this.recoveryAttempts++;}
   else{this.demandSentAt=performance.now();this.recoverySamples=this.diagnosticSamples;}
   const reason=stalled?'provider_stall':'playback_starvation';
   this.socket?.send(JSON.stringify({type:'flush',reason}));
   this.options.trace?.(stalled?'ELEVENLABS_STALL_RECOVERY':'ELEVENLABS_STARVATION_FLUSH',{requestId:this.identity?.requestId,pendingCharacters:pending,bufferMs,leadMs:this.demand.leadMs,reason,recoveryAttempts:this.recoveryAttempts,receivedSamples:this.diagnosticSamples,pcmIdleMs:this.lastPcmAt===undefined?0:performance.now()-this.lastPcmAt});
  }catch(error){this.fail(error instanceof Error?error:new Error('Voice unavailable.'));}
 }
 finish(){clearTimeout(this.greetingTimer);if(this.greeting){const text=this.greeting;this.greeting=undefined;try{this.sendNow(text);}catch(error){return Promise.reject(error);}}this.signal?.throwIfAborted();if(this.failed)return Promise.reject(this.failed);if(this.ending)return Promise.reject(new Error('Voice already finalized.'));this.ending=true;return new Promise<void>((resolve,reject)=>{this.doneResolve=resolve;this.doneReject=reject;this.trace('voice.finish_requested');this.socket?.send(JSON.stringify({type:'finish'}));this.trace('voice.finalization_timeout_started',{timeoutMs:30000,deadlineAt:performance.now()+30000,clock:'browser-performance.now'});this.timer=setTimeout(()=>{this.trace('voice.finalization_timeout_expired',{timeoutMs:30000});this.fail(new Error('Voice finalization timed out.'));},30000);});}
 close(){if(!this.ended)this.provenance?.cancel();this.pendingPcm=undefined;this.pendingAlignment=undefined;this.trace('voice.cleanup');clearInterval(this.demandTimer);clearTimeout(this.greetingTimer);this.greeting=undefined;clearTimeout(this.timer);this.signal?.removeEventListener('abort',this.aborted);if(!this.failed&&!this.ended){this.failed=new DOMException('Call ended','AbortError');this.readyReject?.(this.failed);this.doneReject?.(this.failed);}if(this.socket){this.socket.onmessage=null;this.socket.onclose=null;this.socket.onerror=null;this.socket.close();}this.socket=undefined;}
}
